    adcs_quat_t qa, qb, qa_conj, q_rel;
    double w_abs, d;

    if ((a == NULL) || (b == NULL) || (distance_rad == NULL)) {
        return ADCS_E_NULL;
    }

    *distance_rad = INFINITY;

    if (adcs_quat_normalize(a, &qa) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }
    if (adcs_quat_normalize(b, &qb) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    qa_conj = adcs_quat_conjugate(&qa);
    q_rel = adcs_quat_multiply(&qb, &qa_conj);

    w_abs = fabs(q_rel.w);
    w_abs = ADCS_CLAMP(w_abs, 0.0, 1.0);
    d = 2.0 * acos(w_abs);

    *distance_rad = d;
    return ADCS_OK;
}

